const accent = '\u0301';
const stressIndex = word => word.indexOf(accent) - 1;
const wordStress = new Map(markedWords.trim().split(/\s+/u).map(word => [word.replace(accent, ''), stressIndex(word)]));

// These spellings have more than one reading. Each override is tied to a
// catalog entry, so new examples don't inherit a stress for a different word.
