export function markRussianStress(text, entryId) {
  const contextual = contextualStress[entryId];
  const vowels = /[аеёиоуыэюя]/gu;
  const markWord = word => {
    const lower = word.toLowerCase();
    const explicit = lower.indexOf('ё');
    const index = explicit >= 0 ? ((lower.match(vowels)?.length ?? 0) > 1 ? explicit : undefined)
      : contextual?.replace(accent, '') === lower ? stressIndex(contextual) : wordStress.get(lower);
    return index === undefined ? word : word.slice(0, index + 1) + accent + word.slice(index + 1);
  };
  return text.replace(/[а-яё]+(?:-[а-яё]+)*/giu, token => {
    if (!token.includes('-')) return markWord(token);
    const lower = token.toLowerCase();
    const whole = contextual?.replace(accent, '') === lower ? stressIndex(contextual) : wordStress.get(lower);
    if (whole !== undefined) return token.slice(0, whole + 1) + accent + token.slice(whole + 1);
    return token.split('-').map(markWord).join('-');
  });
}
